document.querySelectorAll('.reveal').forEach((el)=>new IntersectionObserver(([e],o)=>{if(e.isIntersecting){e.target.classList.add('visible');o.disconnect()}},{threshold:.12}).observe(el));
const answers={invest:{report:'Сначала сравним динамику выручки, прибыли и долга. Затем посмотрим мультипликаторы и риски отрасли. Итог - не команда "покупать", а понятная карта аргументов для самостоятельного решения.',risk:'Определим горизонт, допустимую просадку и долю одной компании в портфеле. FinAI покажет, где риск сконцентрирован и какие вопросы стоит задать до сделки.',compare:'Сравним компании по одинаковым метрикам, бизнес-модели и долговой нагрузке - без выбора "победителя" только по одной красивой цифре.'},balance:{budget:'Разложим расходы на обязательные, гибкие и цели. После этого найдем сумму, которую можно направлять в резерв без ощущения жесткой экономии.',debt:'Сравним ставки, минимальные платежи и свободный денежный поток. Получится очередность погашения и безопасная сумма дополнительного платежа.',goal:'Уточним цену цели и срок, учтем резерв и рассчитаем комфортный ежемесячный шаг. Если план слишком напряженный, предложим реалистичные варианты.'},mentor:{skill:'Определим целевую роль, текущий уровень и 3 навыка с самым большим влиянием. Затем соберем короткий план практики на ближайшие две недели.',route:'Разобьем большую цель на модули, мини-проекты и точки проверки. Вы будете видеть не список курсов, а последовательный маршрут.',practice:'FinAI предложит небольшую практическую задачу, проверит ход рассуждений и подскажет, что повторить перед следующим шагом.'},business:{money:'Сопоставим выручку, маржу, постоянные расходы и кассовые разрывы. FinAI подсветит места, где бизнес теряет деньги или ликвидность.',marketing:'Сравним каналы по стоимости лида, конверсии и окупаемости. Итог - гипотезы, что отключить, проверить или масштабировать.',docs:'Выделим сроки, штрафы, ответственность и неоднозначные формулировки. Это первичный разбор, который помогает подготовить вопросы юристу.'}};
document.querySelectorAll('[data-demo]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-demo]').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active');const box=document.querySelector('#demo-answer');const type=document.body.dataset.bot;box.innerHTML='<b>Как разберет FinAI:</b><br>'+answers[type][btn.dataset.demo]}));
